from openpyxl.formatting.rule import FormulaRule
from openpyxl.utils import get_column_letter

OUT = sys.argv[1]
F = 'Arial'
thin = Side(style='thin', color='999999'); B = Border(left=thin, right=thin, top=thin, bottom=thin)
HFILL = PatternFill('solid', fgColor='DDE4EE'); INFILL = PatternFill('solid', fgColor='FFF2CC')
RED = PatternFill('solid', fgColor='F8CBAD'); YEL = PatternFill('solid', fgColor='FFE699'); GRN = PatternFill('solid', fgColor='C6EFCE')
WRAP = Alignment(wrap_text=True, vertical='top')

def sheet(wb, title, headers, widths, rows):
    ws = wb.create_sheet(title)
    ws.append(headers)
    for c in range(1, len(headers) + 1):
        x = ws.cell(1, c); x.font = Font(name=F, bold=True, size=10); x.fill = HFILL
        x.alignment = Alignment(wrap_text=True, vertical='center', horizontal='center'); x.border = B
    for r in rows:
        ws.append(list(r))
    for row in ws.iter_rows(min_row=2, max_row=ws.max_row, max_col=len(headers)):
        for x in row:
            x.font = Font(name=F, size=10); x.alignment = WRAP; x.border = B
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = 'A2'; ws.auto_filter.ref = f'A1:{get_column_letter(len(headers))}{ws.max_row}'
    ws.sheet_view.zoomScale = 90
    return ws

